-- Add `is_ggw` column if it doesn't exist
DO
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_name = 'amp_category_value_location'
          AND column_name = 'is_ggw'
    ) THEN
        ALTER TABLE amp_category_value_location ADD COLUMN is_ggw BOOLEAN DEFAULT FALSE;
    END IF;
END;

-- Add `is_ecowas` column if it doesn't exist
DO
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM information_schema.columns
        WHERE table_name = 'amp_category_value_location'
          AND column_name = 'is_ecowas'
    ) THEN
        ALTER TABLE amp_category_value_location ADD COLUMN is_ecowas BOOLEAN DEFAULT FALSE;
    END IF;
END;

-- Update for GGW countries
UPDATE AMP_CATEGORY_VALUE_LOCATION
SET is_ggw = TRUE
WHERE UPPER(iso) IN (
    'BF', 'TD', 'DJ', 'ER', 'ET',
    'ML', 'MR', 'NE', 'NG', 'SN', 'SD'
);

-- Update for ECOWAS countries
UPDATE AMP_CATEGORY_VALUE_LOCATION
SET is_ecowas = TRUE
WHERE UPPER(iso) IN (
    'BJ', 'BF', 'CV', 'CI', 'GM',
    'GH', 'GN', 'GW', 'LR', 'ML',
    'NE', 'NG', 'SN', 'SL', 'TG'
);
